    // ACE-Lite constants
    // Domain encodings (shareability)
    localparam [1:0] DOMAIN_NON_SHAREABLE = 2'b00;
    localparam [1:0] DOMAIN_INNER_SHAREABLE = 2'b01;
    localparam [1:0] DOMAIN_OUTER_SHAREABLE = 2'b10;
    localparam [1:0] DOMAIN_SYSTEM = 2'b11;

    // Write snoop encodings (ACE-Lite subset)
    localparam [2:0] AWSNOOP_WRITE_NO_SNOOP = 3'b000;
    localparam [2:0] AWSNOOP_WRITE_LINE_UNIQUE = 3'b001;
    localparam [2:0] AWSNOOP_WRITE_CLEAN = 3'b010;
    localparam [2:0] AWSNOOP_WRITE_BACK = 3'b011;
    localparam [2:0] AWSNOOP_EVICT = 3'b100;
    localparam [2:0] AWSNOOP_WRITE_EVICT = 3'b101;

    // Read snoop encodings (ACE-Lite subset)
    localparam [3:0] ARSNOOP_READ_NO_SNOOP = 4'b0000;
    localparam [3:0] ARSNOOP_READ_ONCE = 4'b0001;
    localparam [3:0] ARSNOOP_READ_SHARED = 4'b0001;
    localparam [3:0] ARSNOOP_READ_CLEAN = 4'b0010;
    localparam [3:0] ARSNOOP_READ_NOT_SHARED_DIRTY = 4'b0011;
    localparam [3:0] ARSNOOP_READ_UNIQUE = 4'b0111;
    localparam [3:0] ARSNOOP_CLEAN_UNIQUE = 4'b1011;

    // Barrier type encodings
    localparam [1:0] BAR_NORMAL_ACCESS = 2'b00;
    localparam [1:0] BAR_MEMORY_BARRIER = 2'b01;
    localparam [1:0] BAR_RESERVED = 2'b10;
    localparam [1:0] BAR_SYNC_BARRIER = 2'b11;

    // Internal arbitration wires
    genvar g_m, g_s;
    integer m, ex; // Module-scope integer variables for Verilog-2001
    
    // Module-scope signal arrays
    wire [NUM_SLAVE-1:0] aw_select [NUM_MASTER-1:0];
    wire [NUM_SLAVE-1:0] ar_select [NUM_MASTER-1:0];
    wire [NUM_MASTER-1:0] aw_grant [NUM_SLAVE-1:0];
    wire [NUM_MASTER-1:0] ar_grant [NUM_SLAVE-1:0];
    
    // Address decoder for each master
    generate
        for (g_m = 0; g_m < NUM_MASTER; g_m = g_m + 1) begin : master_decode
            // Simple decode based on upper address bits
            assign aw_select[g_m] = (g_m < NUM_MASTER && M0_AWADDR[31:28] < NUM_SLAVE) ? 
                                   (1 << M0_AWADDR[31:28]) : {NUM_SLAVE{1'b0}};
            assign ar_select[g_m] = (g_m < NUM_MASTER && M0_ARADDR[31:28] < NUM_SLAVE) ? 
                                   (1 << M0_ARADDR[31:28]) : {NUM_SLAVE{1'b0}};
        end
    endgenerate

    // Enhanced Arbitration with Starvation Prevention
    parameter STARVATION_TIMEOUT = 16'd1024;
    parameter ENABLE_STARVATION_PREVENTION = 1'b1;

    // Module-scope arbitration state registers
    reg [5:0] rr_ptr_aw [NUM_SLAVE-1:0];
    reg [5:0] rr_ptr_ar [NUM_SLAVE-1:0];
    wire [NUM_MASTER-1:0] normal_aw_grant [NUM_SLAVE-1:0];
    wire [NUM_MASTER-1:0] normal_ar_grant [NUM_SLAVE-1:0];
    
    // Security Firewall signals
    wire [NUM_MASTER-1:0] aw_firewall_block;
    wire [NUM_MASTER-1:0] ar_firewall_block;
    wire [NUM_MASTER-1:0] aw_violation;
    wire [NUM_MASTER-1:0] ar_violation;
    wire security_alert;
    
    // Security configuration (hardcoded for this example)
    wire [NUM_MASTER-1:0] master_secure = 64'b1111111111111111111111111111111111111111111111111111111100000000;
    wire [NUM_SLAVE-1:0] slave_secure = 32'b11111111111111111111111100000000;
    wire [NUM_SLAVE-1:0] slave_nonsec_allowed = 32'b00000000000000000000000000001111;
    
    
    // Starvation prevention state
    reg [15:0] request_time_s0 [NUM_MASTER-1:0];
    reg [NUM_MASTER-1:0] requesting_s0;
    reg [15:0] global_timer_s0;
    reg [15:0] current_grant_time_s0;
    reg [5:0] current_master_s0;
    reg starvation_override_s0;
    reg [5:0] starved_master_s0;
    reg [15:0] request_time_s1 [NUM_MASTER-1:0];
    reg [NUM_MASTER-1:0] requesting_s1;
    reg [15:0] global_timer_s1;
    reg [15:0] current_grant_time_s1;
    reg [5:0] current_master_s1;
    reg starvation_override_s1;
    reg [5:0] starved_master_s1;
    reg [15:0] request_time_s2 [NUM_MASTER-1:0];
    reg [NUM_MASTER-1:0] requesting_s2;
    reg [15:0] global_timer_s2;
    reg [15:0] current_grant_time_s2;
    reg [5:0] current_master_s2;
    reg starvation_override_s2;
    reg [5:0] starved_master_s2;
    reg [15:0] request_time_s3 [NUM_MASTER-1:0];
