    // Security Firewall Logic
    generate
        for (g_m = 0; g_m < NUM_MASTER; g_m = g_m + 1) begin : master_firewall_check
            if (g_m == 0) begin : master0_security
                // Security check for write channel
                assign aw_firewall_block[0] = M0_AWVALID && (
                    // Check if non-secure master accessing secure slave
                    (!master_secure[0] && |(aw_select[0] & slave_secure) &&
                     !(|(aw_select[0] & slave_nonsec_allowed))) ||
                    // Check AxPROT[1] for secure/non-secure transaction
                    (M0_AWPROT[1] && |(aw_select[0] & slave_secure) &&
                     !(|(aw_select[0] & slave_nonsec_allowed)))
