                    cache_lru[victim_index] <= 8'h00;
                    cache_owner[victim_index][59] <= 1'b1;
                    cache_misses <= cache_misses + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Clear other masters' ownership of this line
                    for (k = 0; k < NUM_MASTER; k = k + 1) begin
                        if (k != 59) begin
                            cache_state[victim_index][k] <= STATE_INVALID;
                            cache_owner[victim_index][k] <= 1'b0;
                        end
                    end
                end
            end
            
            // Clear coherency conflict flag after one cycle
            coherency_conflict[59] <= 1'b0;
            
            // Master 60 state update processing
            if (m60_state_update) begin
                if (cache_hit[60]) begin
                    // Update existing cache line
                    cache_state[cache_index[60]][60] <= m60_new_state;
                    cache_lru[cache_index[60]] <= 8'h00;  // Mark as most recent
                    cache_hits <= cache_hits + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Check for coherency conflicts
                    if (m60_new_state == STATE_MODIFIED || m60_new_state == STATE_EXCLUSIVE) begin
                        for (k = 0; k < NUM_MASTER; k = k + 1) begin
                            if (k != 60 && cache_state[cache_index[60]][k] != STATE_INVALID) begin
                                coherency_conflict[60] <= 1'b1;
                                // Invalidate other masters' copies
                                cache_state[cache_index[60]][k] <= STATE_INVALID;
                            end
                        end
                    end
                    
                end else begin
                    // Allocate new cache line
                    cache_valid[victim_index] <= 1'b1;
