    , input  wire [15:0]            m63_tlb_asid       // Address Space ID
    , input  wire [2:0]             m63_tlb_op         // TLB operation type
    , input  wire                   m63_tlb_valid      // TLB request valid
    , output reg                    m63_tlb_ready      // TLB request ready
    , output reg                    m63_tlb_complete   // TLB operation complete
