                // Complete the TLB operation
                tlb_op_complete[63] <= 1'b1;
                tlb_op_pending[63] <= 1'b0;
                m63_tlb_ready <= 1'b1;
                m63_tlb_complete <= 1'b1;
                m63_tlb_entries_inv <= invalidation_counter[63];
                
                // Update statistics
                tlb_total_invalidations <= tlb_total_invalidations + invalidation_counter[63];
                
                // Set response based on operation result
                if (tlb_maintenance_error[63]) begin
                    m63_tlb_resp <= TLB_RESP_ERROR;
                end else if (invalidation_counter[63] == 0 && m63_tlb_op != TLB_SYNC) begin
                    m63_tlb_resp <= TLB_RESP_PARTIAL;
                end else begin
                    m63_tlb_resp <= TLB_RESP_OK;
                end
                
            end else if (tlb_op_complete[63]) begin
                // Clear completion flag
                tlb_op_complete[63] <= 1'b0;
                m63_tlb_complete <= 1'b0;
                
                // Clear error flag
                tlb_maintenance_error[63] <= 1'b0;
            end
            
            // Update valid entry count for master 63
            tlb_entries_per_master[63] <= 0;
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                if (tlb_valid[63][k]) begin
                    tlb_entries_per_master[63] <= tlb_entries_per_master[63] + 1;
                end
            end
            
            // Update global TLB invalidation status
            tlb_invalidation_active <= |tlb_op_pending;
            
        end
    end

