    // ACE-Lite Configuration and Status
    , input  wire                      ace_lite_enable
    , input  wire                      coherency_enable
    , input  wire                      snoop_filter_enable
    , input  wire                      barrier_enable
    , input  wire                      cache_ops_enable
    , output wire                      coherency_violation
    , output wire                      barrier_active
    , output wire [7:0]                cache_ops_pending
    , output wire [NUM_MASTER-1:0]     master_coherency_state
);

    // Internal signals for modular ACE-Lite components
    // Coherency Controller signals
    wire [NUM_MASTER-1:0] coherency_block;
    wire [NUM_MASTER-1:0] coherency_violation_per_master;
    wire coherency_active;
    wire [NUM_MASTER-1:0] transaction_valid;
    wire [7:0] coherency_state [NUM_MASTER-1:0];

    // Snoop Filter signals
    wire [NUM_MASTER-1:0] snoop_required;
    wire [NUM_MASTER-1:0] snoop_block;
    wire [WIDTH_AD-1:0] snoop_target_addr;
    wire [NUM_MASTER-1:0] snoop_target_masters;
    wire [7:0] filter_hit_count;
    wire [7:0] filter_miss_count;
    wire [NUM_MASTER-1:0] invalidate_required;
    wire [WIDTH_AD-1:0] invalidate_addr;
    wire [2:0] invalidate_type;
    wire invalidate_valid;
    wire [NUM_MASTER-1:0] conflict_detected;
    wire [WIDTH_AD-1:0] conflict_addr;
    wire [CONFLICT_COUNT_WIDTH-1:0] conflict_count;

    // Barrier Synchronization signals
    wire [NUM_MASTER-1:0] barrier_active_per_master;
    wire [NUM_MASTER-1:0] barrier_block;
    wire [NUM_MASTER-1:0] barrier_timeout;
    wire [15:0] pending_transactions [NUM_MASTER-1:0];

    // Domain Manager signals
    wire [1:0] resolved_awdomain [NUM_MASTER-1:0];
    wire [1:0] resolved_ardomain [NUM_MASTER-1:0];
    wire [3:0] domain_active;
    wire [NUM_MASTER-1:0] coherency_required;
    wire [NUM_MASTER-1:0] domain_violation;
    wire [7:0] domain_transaction_count [3:0];

    // Cache Operations signals
    wire [NUM_MASTER-1:0] cache_op_active;
    wire [NUM_MASTER-1:0] cache_maint_required;
    wire [3:0] cache_op_type [NUM_MASTER-1:0];
    wire [WIDTH_AD-1:0] cache_op_addr [NUM_MASTER-1:0];
    wire [7:0] cache_op_pending_count;
    wire [7:0] cache_clean_count;
    wire [7:0] cache_invalidate_count;

    // Master interface control with ACE-Lite blocking
    wire M0_AWREADY_internal;
    wire M0_ARREADY_internal;
    assign M0_AWREADY = M0_AWREADY_internal && 
                        !(coherency_enable && coherency_block[0]) &&
                        !(barrier_enable && barrier_block[0]) &&
                        !(snoop_filter_enable && snoop_block[0]);
    assign M0_ARREADY = M0_ARREADY_internal && 
